import{_ as t,o as a,c as o,ai as n}from"./chunks/framework.C33Uq6m-.js";const r="/llmxray/docs/educators/hallucination-pipeline.svg",i="/llmxray/docs/educators/confidence-vs-truth.svg",s="/llmxray/docs/educators/benchmark-comparison.svg",f=JSON.parse('{"title":"Module 3: Can AI Lie?","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/module-3.md","filePath":"en/community/educators/module-3.md"}'),l={name:"en/community/educators/module-3.md"};function h(d,e,c,u,m,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="module-3-can-ai-lie" tabindex="-1">Module 3: Can AI Lie? <a class="header-anchor" href="#module-3-can-ai-lie" aria-label="Permalink to &quot;Module 3: Can AI Lie?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>The Skeptic</strong> — Discover the difference between confidence and truth</p><p><strong>Duration:</strong> 90 min | <strong>Difficulty:</strong> Intermediate | <strong>Prerequisite:</strong> <a href="./module-1.html">Module 1</a>, <a href="./module-2.html">Module 2</a></p></div><h2 id="the-aha-moment" tabindex="-1">The Aha Moment <a class="header-anchor" href="#the-aha-moment" aria-label="Permalink to &quot;The Aha Moment&quot;">​</a></h2><blockquote><p>A model can be 95% confident and completely wrong. Confidence measures prediction certainty, not factual accuracy.</p></blockquote><p>This module destroys the assumption that &quot;the model sounds confident, so it must be right.&quot; Students discover that logprobs measure how often a pattern appeared in training data — not whether the pattern is true.</p><hr><h2 id="conceptual-background" tabindex="-1">Conceptual Background <a class="header-anchor" href="#conceptual-background" aria-label="Permalink to &quot;Conceptual Background&quot;">​</a></h2><h3 id="what-does-hallucination-mean" tabindex="-1">What does &quot;hallucination&quot; mean? <a class="header-anchor" href="#what-does-hallucination-mean" aria-label="Permalink to &quot;What does &quot;hallucination&quot; mean?&quot;">​</a></h3><p>In AI, <strong>hallucination</strong> refers to a model generating text that is fluent and confident but factually incorrect, fabricated, or unsupported. The model doesn&#39;t &quot;intend&quot; to deceive — it generates the most probable continuation based on patterns, and sometimes the most probable continuation is wrong.</p><p>Hallucination is not a bug — it&#39;s the <strong>default behavior</strong> of autoregressive language models. Every token the model generates is a statistical prediction, not a fact lookup. When the training data contains incorrect information (popular misconceptions, outdated facts, fiction), the model learns those patterns just as readily as true ones.</p><h3 id="why-models-fabricate-facts" tabindex="-1">Why models fabricate facts <a class="header-anchor" href="#why-models-fabricate-facts" aria-label="Permalink to &quot;Why models fabricate facts&quot;">​</a></h3><p><img src="'+r+'" alt="Why LLMs Hallucinate"></p><p>Key insight: there is no &quot;knowledge database&quot; inside an LLM. When you ask &quot;What is the capital of France?&quot;, the model doesn&#39;t look up a fact. It computes: <em>given the context &quot;What is the capital of France?&quot;, what token is most likely to come next?</em> The answer is &quot;Paris&quot; because the pattern &quot;capital of France&quot; → &quot;Paris&quot; appeared thousands of times in the training data.</p><p>This works well for common facts. But for uncommon questions, the model still predicts the &quot;most likely&quot; continuation — even when that continuation is a fabrication. The model cannot distinguish between &quot;I saw this pattern in reliable sources&quot; and &quot;I saw this pattern in fiction.&quot;</p><h3 id="confidence-is-not-truth" tabindex="-1">Confidence is not truth <a class="header-anchor" href="#confidence-is-not-truth" aria-label="Permalink to &quot;Confidence is not truth&quot;">​</a></h3><p>LLMs produce a probability distribution over the vocabulary at each step. The probability (or its logarithm, the <strong>logprob</strong>) represents how certain the model is about its prediction. But this certainty is about <strong>pattern frequency</strong>, not <strong>factual accuracy</strong>.</p><p><img src="'+i+'" alt="Confidence vs Truth"></p><p>A model can assign 95% probability to the wrong answer if:</p><ul><li>The wrong answer is a <strong>common misconception</strong> (&quot;humans use 10% of their brain&quot;)</li><li>The question contains a <strong>false premise</strong> the model accepts (&quot;When did Napoleon invade Brazil?&quot;)</li><li>The model is <strong>sycophantic</strong> — it agrees with whatever the user implies</li></ul><h3 id="sycophancy-models-that-agree-with-you" tabindex="-1">Sycophancy: models that agree with you <a class="header-anchor" href="#sycophancy-models-that-agree-with-you" aria-label="Permalink to &quot;Sycophancy: models that agree with you&quot;">​</a></h3><p>When you ask a leading question (&quot;Don&#39;t you think that X is true?&quot;), many models will agree — even if X is false. This is called <strong>sycophancy</strong>. The model learned from training data where agreeable responses were common (customer service, polite conversation), and it generalizes that pattern even when agreement means saying something untrue.</p><h3 id="different-benchmarks-measure-different-things" tabindex="-1">Different benchmarks measure different things <a class="header-anchor" href="#different-benchmarks-measure-different-things" aria-label="Permalink to &quot;Different benchmarks measure different things&quot;">​</a></h3><p><img src="'+s+'" alt="Different Benchmarks Test Different Things"></p><p>A model can score 72% on science reasoning (ARC) but only 41% on truthfulness (TruthfulQA). This isn&#39;t contradictory — it means the model learned scientific patterns correctly but also learned popular misconceptions. Both patterns coexist in the same weights.</p><hr><h2 id="hands-on-exercises" tabindex="-1">Hands-On Exercises <a class="header-anchor" href="#hands-on-exercises" aria-label="Permalink to &quot;Hands-On Exercises&quot;">​</a></h2><h3 id="exercise-1-the-confident-fabrication" tabindex="-1">Exercise 1: The confident fabrication <a class="header-anchor" href="#exercise-1-the-confident-fabrication" aria-label="Permalink to &quot;Exercise 1: The confident fabrication&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open <strong>Chat Diagnostics</strong> in LLMxRay</li><li>Ask the model these questions, one at a time: <ul><li><em>&quot;What year did Napoleon invade Brazil?&quot;</em> (He never did)</li><li><em>&quot;Who wrote the novel &#39;The Shadows of Tomorrow&#39; by Margaret Chen?&quot;</em> (This book doesn&#39;t exist)</li><li><em>&quot;What is the airspeed velocity of an unladen swallow in meters per second?&quot;</em> (A joke question from Monty Python)</li></ul></li><li>For each response, observe: <ul><li>Does the model answer confidently?</li><li>Does it fabricate specific details (dates, publisher names, exact numbers)?</li><li>Does it warn you that the premise might be wrong?</li></ul></li></ol><p><strong>What you&#39;ll discover:</strong></p><p>Most models will confidently provide a year for Napoleon&#39;s &quot;invasion&quot; of Brazil, invent an author biography for a non-existent book, and give a precise airspeed for the Monty Python question. The model generates these fabrications because the <em>pattern</em> of answering factual questions with specific details is very strong in training data.</p><div class="warning custom-block"><p class="custom-block-title">Not all models behave the same</p><p>Some newer models (especially those trained with RLHF or constitutional AI) may push back on false premises. If your model says &quot;Napoleon never invaded Brazil,&quot; try a less obvious false premise. The point is that fabrication is always possible — not that it happens every time.</p></div><hr><h3 id="exercise-2-benchmark-—-truthfulqa" tabindex="-1">Exercise 2: Benchmark — TruthfulQA <a class="header-anchor" href="#exercise-2-benchmark-—-truthfulqa" aria-label="Permalink to &quot;Exercise 2: Benchmark — TruthfulQA&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open the <strong>Benchmark</strong> page in LLMxRay</li><li>Select a model and run the <strong>TruthfulQA</strong> suite</li><li>While it runs, watch the live progress — note how many questions the model gets wrong</li><li>After completion, analyze: <ul><li><strong>Overall accuracy</strong> — What percentage did the model get right?</li><li><strong>Per-category breakdown</strong> — Which categories are weakest?</li><li><strong>Confidence distribution</strong> — Look at the logprob data for wrong answers</li></ul></li></ol><p><strong>What to focus on:</strong></p><p>Find questions where the model was <strong>highly confident but wrong</strong>. These are the dangerous cases — in a production system, you couldn&#39;t tell from the model&#39;s confidence that the answer was incorrect.</p><p>TruthfulQA specifically tests common misconceptions. Questions like &quot;Can you see the Great Wall of China from space?&quot; (No, you can&#39;t) or &quot;Do we use only 10% of our brains?&quot; (No, we use all of it). The model learned these myths from training data alongside correct information.</p><hr><h3 id="exercise-3-confidence-vs-correctness-analysis" tabindex="-1">Exercise 3: Confidence vs correctness analysis <a class="header-anchor" href="#exercise-3-confidence-vs-correctness-analysis" aria-label="Permalink to &quot;Exercise 3: Confidence vs correctness analysis&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>From your TruthfulQA benchmark results, identify: <ul><li>3 questions where <strong>high confidence + correct answer</strong> (expected — good)</li><li>3 questions where <strong>low confidence + correct answer</strong> (lucky — uncertain but right)</li><li>3 questions where <strong>high confidence + wrong answer</strong> (dangerous — confident but wrong)</li><li>3 questions where <strong>low confidence + wrong answer</strong> (expected — uncertain and wrong)</li></ul></li><li>Record the logprob values for each</li><li>Calculate: What percentage of high-confidence answers were actually correct?</li></ol><p><strong>Discussion:</strong></p><ul><li>Is there a logprob threshold above which you can &quot;trust&quot; the model?</li><li>If you were building a medical chatbot, how would you handle the &quot;high confidence + wrong answer&quot; cases?</li><li>Would you rather have a model that&#39;s often uncertain but rarely wrong, or one that&#39;s usually confident but sometimes dangerously wrong?</li></ul><hr><h3 id="exercise-4-the-benchmark-comparison" tabindex="-1">Exercise 4: The benchmark comparison <a class="header-anchor" href="#exercise-4-the-benchmark-comparison" aria-label="Permalink to &quot;Exercise 4: The benchmark comparison&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Run <strong>ARC</strong> (science reasoning) on the same model you used for TruthfulQA</li><li>Compare the results: <ul><li>ARC accuracy vs TruthfulQA accuracy</li><li>Which is higher? By how much?</li></ul></li><li>Look at the per-category breakdowns of both</li><li>Find a topic where the model does well on ARC but poorly on TruthfulQA (or vice versa)</li></ol><p><strong>Why this matters:</strong></p><p>ARC tests knowledge that the model learned from scientific text — textbooks, papers, educational content. This knowledge is generally correct.</p><p>TruthfulQA tests resistance to misconceptions — beliefs that are popular but wrong. These misconceptions also appeared in training data (news articles, social media, casual conversation).</p><p>The model learned <strong>both</strong> equally well. It can&#39;t distinguish truth from popular fiction because both are just patterns in text.</p><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>Hallucination is the default</strong>, not the exception. Models generate predictions, not facts.</li><li><strong>Confidence measures pattern frequency</strong>, not truth. A common misconception gets high confidence.</li><li><strong>Models are sycophantic</strong> — they tend to agree with false premises instead of pushing back.</li><li><strong>Different benchmarks test different dimensions.</strong> High ARC score doesn&#39;t mean high truthfulness.</li><li><strong>Logprobs alone cannot tell you if an answer is correct.</strong> External verification is always needed for high-stakes applications.</li></ol><hr><h2 id="discussion-questions" tabindex="-1">Discussion Questions <a class="header-anchor" href="#discussion-questions" aria-label="Permalink to &quot;Discussion Questions&quot;">​</a></h2><ol><li>If hallucination is inherent to how LLMs work, can it ever be fully &quot;solved&quot;? What would that require?</li><li>A hospital wants to use an LLM for patient triage. Given what you know about confidence vs truth, what safeguards would you design?</li><li>TruthfulQA tests English-language misconceptions. Would the same model score differently on misconceptions common in French or Chinese culture? Why?</li><li>Is sycophancy always bad? Can you think of scenarios where a model agreeing with the user is actually the right behavior?</li><li>RAG (Retrieval-Augmented Generation) is proposed as a solution to hallucination — the model retrieves real documents before answering. Does this fully solve the problem? What could still go wrong?</li></ol><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><h3 id="academic-papers" tabindex="-1">Academic Papers <a class="header-anchor" href="#academic-papers" aria-label="Permalink to &quot;Academic Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paper</th><th>Authors</th><th>Year</th><th>Link</th></tr></thead><tbody><tr><td>TruthfulQA: Measuring How Models Mimic Human Falsehoods</td><td>Lin, Hilton, Evans</td><td>2022</td><td><a href="https://arxiv.org/abs/2109.07958" target="_blank" rel="noreferrer">arXiv:2109.07958</a></td></tr><tr><td>A Survey on Hallucination in Large Language Models</td><td>Huang et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2311.05232" target="_blank" rel="noreferrer">arXiv:2311.05232</a></td></tr><tr><td>Sycophancy in Large Language Models</td><td>Sharma, Tong, Korbak, Duvenaud, Askell et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2310.13548" target="_blank" rel="noreferrer">arXiv:2310.13548</a></td></tr><tr><td>Language Models (Mostly) Know What They Know</td><td>Kadavath et al. (Anthropic)</td><td>2022</td><td><a href="https://arxiv.org/abs/2207.05221" target="_blank" rel="noreferrer">arXiv:2207.05221</a></td></tr><tr><td>Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks</td><td>Lewis et al.</td><td>2020</td><td><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">arXiv:2005.11401</a></td></tr><tr><td>On Calibration of Modern Neural Networks</td><td>Guo, Pleiss, Sun, Weinberger</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.04599" target="_blank" rel="noreferrer">arXiv:1706.04599</a></td></tr></tbody></table><h3 id="benchmark-papers" tabindex="-1">Benchmark Papers <a class="header-anchor" href="#benchmark-papers" aria-label="Permalink to &quot;Benchmark Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Benchmark</th><th>Paper</th><th>Link</th></tr></thead><tbody><tr><td>ARC</td><td>Think you have Solved Question Answering? (Clark et al., 2018)</td><td><a href="https://arxiv.org/abs/1803.05457" target="_blank" rel="noreferrer">arXiv:1803.05457</a></td></tr><tr><td>MMLU</td><td>Measuring Massive Multitask Language Understanding (Hendrycks et al., 2021)</td><td><a href="https://arxiv.org/abs/2009.03300" target="_blank" rel="noreferrer">arXiv:2009.03300</a></td></tr><tr><td>HellaSwag</td><td>Can a Machine Really Finish Your Sentence? (Zellers et al., 2019)</td><td><a href="https://arxiv.org/abs/1905.07830" target="_blank" rel="noreferrer">arXiv:1905.07830</a></td></tr></tbody></table><h3 id="tutorials-and-explanations" tabindex="-1">Tutorials and Explanations <a class="header-anchor" href="#tutorials-and-explanations" aria-label="Permalink to &quot;Tutorials and Explanations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Author</th><th>Link</th></tr></thead><tbody><tr><td>The Illustrated Retrieval Augmented Generation</td><td>Lilian Weng</td><td><a href="https://lilianweng.github.io/posts/2023-06-23-agent/" target="_blank" rel="noreferrer">lilianweng.github.io</a></td></tr><tr><td>Controllable Neural Text Generation</td><td>Lilian Weng</td><td><a href="https://lilianweng.github.io/posts/2021-01-02-controllable-text-generation/" target="_blank" rel="noreferrer">lilianweng.github.io</a></td></tr><tr><td>Prompt Engineering Guide — Risks and Misuses</td><td>DAIR.AI</td><td><a href="https://www.promptingguide.ai/risks" target="_blank" rel="noreferrer">promptingguide.ai</a></td></tr></tbody></table><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p><strong>Option A — Case study (individual, 1 page):</strong> Find 3 examples of confident fabrication using LLMxRay. For each: quote the prompt, quote the fabricated response, explain why the model fabricated it (what training pattern caused it), and show the confidence level from the Stream tab.</p><p><strong>Option B — Benchmark analysis (pairs, slide deck):</strong> Run both ARC and TruthfulQA on the same model. Present a 5-8 slide analysis: overall scores, per-category comparison, 3 examples of &quot;knows science but believes myths,&quot; and a policy recommendation for a company deploying this model.</p><p><strong>Option C — Safety design (groups, 500 words):</strong> Your team is building an AI assistant for a law firm. Given your experiments with confidence and hallucination, design a safety system: When should the model answer directly? When should it flag uncertainty? When should it refuse to answer? Justify every decision with data from your LLMxRay experiments.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p>In <strong><a href="./module-4.html">Module 4: What Does the Model See?</a></strong>, you&#39;ll explore how models represent meaning as vectors. You&#39;ll discover that &quot;I love this&quot; and &quot;I hate this&quot; are <strong>similar</strong> to the model — it sees topic, not sentiment. Understanding embeddings is key to understanding why RAG works (and when it doesn&#39;t).</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 3 of 8</strong> in the LLMxRay Educators Kit <a href="./module-2.html">← Module 2: How Does Temperature Work?</a> | <a href="./index.html">Back to Curriculum</a> | <a href="./module-4.html">Module 4: What Does the Model See? →</a></p></div>',77)])])}const b=t(l,[["render",h]]);export{f as __pageData,b as default};
